<?php $url = static fn(string $parent = ''): string => '/files?' . http_build_query(['space' => $data['space']['id'], 'parent' => $parent]); ?>
<nav class="folder-path" aria-label="Ordnerpfad"><a href="/files">Dateien</a><span aria-hidden="true">/</span><a href="<?= $e($url()) ?>"><?= $e($data['space']['name']) ?></a><?php if($data['folder']!==null): ?><span aria-hidden="true">/</span><span aria-current="page"><?= $e($data['folder']['name']) ?></span><?php endif ?></nav>
<div class="page-heading"><div><h1><?= $e($data['folder']['name'] ?? $data['space']['name']) ?></h1><p class="subtle"><?= $e(number_format($data['used'] / 1048576, 2, ',', '.')) ?> von <?= $e(number_format((int)$data['space']['quota_bytes'] / 1048576, 0, ',', '.')) ?> MiB belegt, einschließlich Versionen und Papierkorb</p></div><?php if($data['folder']!==null): ?><a class="button button-outline" href="<?= $e($url($data['folder']['parent_id'])) ?>">Übergeordneter Ordner</a><?php endif ?></div>
<div class="file-toolbar">
<?php if($data['can_create']): ?><details class="toolbar-disclosure"><summary class="button">Datei hochladen</summary><form class="disclosure-content settings-form" method="post" action="/files/upload" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><input type="hidden" name="parent" value="<?= $e($data['parent']) ?>"><label for="upload-file">Datei, maximal <?= $e(number_format($data['upload_max_bytes']/1048576,2,',','.')) ?> MiB</label><input id="upload-file" type="file" name="file" required><button class="button" type="submit">Hochladen</button><p class="field-note">Vorhandene Dateien werden nicht überschrieben. Der Server kann eine niedrigere Uploadgrenze vorgeben.</p></form></details>
<details class="toolbar-disclosure" <?= ($data['retry_folder']??false)?'open':'' ?>><summary class="button button-outline">Neuer Ordner</summary><form class="disclosure-content settings-form" method="post" action="/files/folder"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><input type="hidden" name="parent" value="<?= $e($data['parent']) ?>"><label for="folder-name">Ordnername</label><input id="folder-name" name="name" value="<?= $e($data['folder_name']??'') ?>" required maxlength="255"><button class="button" type="submit">Anlegen</button></form></details><?php endif ?>
<a class="button button-outline" href="<?= $e('/files/search?'.http_build_query(['space'=>$data['space']['id']])) ?>">Suchen</a>
<details class="toolbar-disclosure"><summary class="button button-outline">Weitere Aktionen</summary><div class="disclosure-content action-links">
<?php if($data['can_catalog_read']??false): ?><a href="<?= $e('/catalog/search?'.http_build_query(['space'=>$data['space']['id']])) ?>">Beschreibungen und Tags durchsuchen</a><?php endif ?>
<?php if($data['can_tag_batch']??false): ?><a href="<?= $e('/catalog/batch?'.http_build_query(['space'=>$data['space']['id'],'parent'=>$data['parent']])) ?>">Tags für mehrere Dateien ändern</a><?php endif ?>
<?php if($data['can_view_trash']): ?><a href="<?= $e('/files/trash?'.http_build_query(['space'=>$data['space']['id']])) ?>">Papierkorb öffnen</a><?php endif ?>
<?php if($caps['access.profiles.manage']??false): ?><a href="<?= $e('/permissions?'.http_build_query(['space'=>$data['space']['id']])) ?>">Zugriff verwalten</a><?php endif ?><a href="/exports">Meine Exporte</a></div></details></div>
<?php if($data['can_export']??false): ?><form id="export-selection" method="post" action="/exports/create" class="selection-bar"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space']['id']) ?>"><span data-selection-count role="status" aria-live="polite">Dateien für Export markieren</span><button class="button button-outline" type="submit">ZIP-Export beauftragen</button><button class="button button-outline" type="button" data-selection-clear hidden>Auswahl aufheben</button><span class="field-note">Nur markierte Dateien dieser Seite. Originale enthalten ihre eingebetteten Metadaten.</span></form><?php endif ?>
<section class="panel"><div class="panel-heading"><h2>Inhalt</h2><span class="subtle"><?= ($data['can_export']??false)?'Für ZIP-Export markieren · ':'' ?>Bis zu 100 Einträge pro Seite</span></div><div class="group-list">
<?php foreach ($data['rows'] as $row): ?><article class="group-row file-row"><div><?php if(($data['can_export']??false)&&$row['kind']==='file'): ?><label class="checkbox-label"><input type="checkbox" form="export-selection" name="entries[]" value="<?= $e($row['id'].':'.$row['revision']) ?>"> <span class="sr-only"><?= $e($row['name']) ?> für Export auswählen</span></label><?php endif ?><h3><?php if ($row['kind'] === 'folder'): ?><a href="<?= $e($url($row['id'])) ?>"><?= $e($row['name']) ?></a><?php else: ?><a href="<?= $e('/files/detail?'.http_build_query(['space'=>$data['space']['id'],'entry'=>$row['id']])) ?>"><?= $e($row['name']) ?></a><?php endif ?></h3><p class="subtle"><?= $row['kind'] === 'folder' ? 'Ordner' : $e(number_format((int) $row['size_bytes'], 0, ',', '.')) . ' Bytes' ?></p><a href="<?= $e('/files/detail?' . http_build_query(['space' => $data['space']['id'], 'entry' => $row['id']])) ?>">Details und Aktionen</a></div><?php if ($row['kind'] === 'file' && $data['can_read']): ?><a class="button button-outline" href="<?= $e('/files/download?' . http_build_query(['space' => $data['space']['id'], 'entry' => $row['id']])) ?>">Herunterladen</a><?php endif ?></article><?php endforeach ?>
<?php if ($data['rows'] === []): ?><p class="empty">Dieser Ordner ist leer. Nutze „Datei hochladen“ oder „Neuer Ordner“, sofern für dich freigegeben.</p><?php endif ?></div>
<?php if ($data['next'] !== null): ?><div class="panel-foot"><a href="<?= $e($url($data['parent']) . '&after=' . rawurlencode($data['next'])) ?>">Weitere Einträge</a></div><?php endif ?></section>

